//! Record field tables generated from the vendored EPICS `.dbd` record
//! declarations — the machine-readable spec every `FieldDesc` used to be
//! hand-copied from.
//!
//! @generated by `tools/dbd-codegen` from `crates/motor-rs/dbd/*.dbd`.
//! DO NOT EDIT. Re-run `cargo run -p dbd-codegen -- --write` after changing a
//! vendored `.dbd`. Drift is caught by `dbd_codegen::tests::generated_files_are_not_stale`,
//! which `cargo nextest run` executes — locally and in CI — so a stale table
//! is a failing test, not a comment asking you to remember.
//!
//! What is *not* here, and why:
//!
//! * **`dbCommon` fields.** The port models them once in
//!   [`CommonFields`](epics_base_rs::server::record::CommonFields), so splicing them
//!   into every record table would double-declare them. Base's table emits
//!   them separately as `DB_COMMON_FIELDS` so the two models can be reconciled
//!   (and so a `dbCommon` addition is a diff, not a silent gap).
//! * **`DBF_NOACCESS` fields** (`RSET`, `DPVT`, `MLOK`, `BPTR`, `PPN`, ...).
//!   These are C-internal pointers with no CA/PVA representation — C's
//!   `mapDBFToDBR` sends them to `DBR_NOACCESS` and `dbChannelCreate` refuses
//!   a channel on them. A Rust port has no pointer to expose, so their
//!   *descriptors* are dropped rather than invented — but their NAMES are
//!   kept (`record_noaccess_fields`): C's `dbNameToAddr` resolves them, so
//!   a SEARCH for `REC.BPTR` is answered and the refusal lands at channel
//!   creation, and the search gate needs the names to do the same.

#![allow(clippy::all)]

use epics_base_rs::server::record::{Asl, FieldDesc, Special};
use epics_base_rs::types::DbFieldType;

// ---------------------------------------------------------------------
// `menu(...)` choice tables. The index is the stored `epicsEnum16` and is
// wire-visible (a `DBF_MENU` field is served as `DBR_ENUM`), so the order
// here is the `.dbd` declaration order, verbatim.
// ---------------------------------------------------------------------

/// `menu(motorACCU)`
pub static MENU_MOTOR_ACCU: &[&str] = &["Use ACCL", "Use ACCS"];

/// `menu(motorDIR)`
pub static MENU_MOTOR_DIR: &[&str] = &["Pos", "Neg"];

/// `menu(motorFOFF)`
pub static MENU_MOTOR_FOFF: &[&str] = &["Variable", "Frozen"];

/// `menu(motorMODE)`
pub static MENU_MOTOR_MODE: &[&str] = &["Position", "Velocity"];

/// `menu(motorRMOD)`
pub static MENU_MOTOR_RMOD: &[&str] = &["Default", "Arithmetic", "Geometric", "In-Position"];

/// `menu(motorRSTM)`
pub static MENU_MOTOR_RSTM: &[&str] = &["Never", "Always", "NearZero", "Conditional"];

/// `menu(motorSET)`
pub static MENU_MOTOR_SET: &[&str] = &["Use", "Set"];

/// `menu(motorSPMG)`
pub static MENU_MOTOR_SPMG: &[&str] = &["Stop", "Pause", "Move", "Go"];

/// `menu(motorSTUP)`
pub static MENU_MOTOR_STUP: &[&str] = &["OFF", "ON", "BUSY"];

/// `menu(motorTORQ)`
pub static MENU_MOTOR_TORQ: &[&str] = &["Disable", "Enable"];

/// `menu(motorUEIP)`
pub static MENU_MOTOR_UEIP: &[&str] = &["No", "Yes"];

/// Every `menu()` declared by a vendored `.dbd`, keyed by its EPICS name.
///
/// This is the table `get_enum_strs` answers a `DBF_MENU` field from: the
/// field's [`FieldDesc::menu`] already points at its choices, and this map
/// exists for the by-name lookups (`.db` loading, `dbpr`).
pub fn menu_choices(menu: &str) -> Option<&'static [&'static str]> {
    Some(match menu {
        "motorACCU" => MENU_MOTOR_ACCU,
        "motorDIR" => MENU_MOTOR_DIR,
        "motorFOFF" => MENU_MOTOR_FOFF,
        "motorMODE" => MENU_MOTOR_MODE,
        "motorRMOD" => MENU_MOTOR_RMOD,
        "motorRSTM" => MENU_MOTOR_RSTM,
        "motorSET" => MENU_MOTOR_SET,
        "motorSPMG" => MENU_MOTOR_SPMG,
        "motorSTUP" => MENU_MOTOR_STUP,
        "motorTORQ" => MENU_MOTOR_TORQ,
        "motorUEIP" => MENU_MOTOR_UEIP,
        _ => return None,
    })
}

